-- 13 · Investor data cleanup (one-off, run after 12_industry_taxonomy.sql)
-- 1) Repair text garbled by a CSV read as Latin-1 (e.g. 'Ãle-de-France' → 'Île-de-France').
create or replace function public.fix_mojibake(t text) returns text
language plpgsql immutable as $$
begin
  if t is null or t !~ '[ÃÅÄÂâ]' then return t; end if;
  return convert_from(convert_to(t, 'LATIN1'), 'UTF8');
exception when others then return t;  -- leave anything that is not clean Latin-1 → UTF-8 mojibake untouched
end $$;
update public.investors set
  full_name = fix_mojibake(full_name), organization = fix_mojibake(organization),
  geography = fix_mojibake(geography), notes = fix_mojibake(notes)
where coalesce(full_name,'') || coalesce(organization,'') || coalesce(geography,'') || coalesce(notes,'') ~ '[ÃÅÄÂâ]';

-- 2) Inferred sectors (sector_source = 'inferred'): corporate VCs from the parent company recorded
--    as "Corporate VC Arm" at import; fund-of-funds list → Generalist unless the firm has a known focus.
--    Only rows with no sectors are touched. Industries are derived by the trigger from migration 12.
